    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (K + 8)) a1 a2 (Z_to_bv 64 cur)
             (Z_to_bv 64 (Z.shiftr K 3 + 2147450880)) (Z_to_bv 64 (Z.shiftr (K + 8) 3 + 2147450880)) a6 a7
             s2 s3 (Z_to_bv 64 K) s5 s6 s7 s8 (Z_to_bv 64 2147450880) s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_DAS_LOOP) fc None m (seg_rom asegs)).
