(* [comment removed for export] *)
Definition das_saved (s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list cell :=
  [C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Section W.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

Lemma das_exit : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' xs1 xs3 xs4 xs5 xs6 xs9 xs10 : word)
    (r svc owner first kti kid spa lo shi ff fp : Z) (LB : list block) (LF : list fframe) (S0 : svch) (m mx : mem)
    (pad : list cell) (hjunk sh16 : list byte) (bflag : byte),
  rw_cells asegs mx spa pad -> Z.of_nat (cells_size pad) = bv_unsigned sp + -96 - spa -> lo <= spa ->
  rw_cells asegs mx (bv_unsigned sp + -96) (das_saved s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells asegs mx fp [C1 bflag] ->
  stk asegs mx lo spa -> mem_inv asegs mx ->
